ALTER POLICY "Authenticated users can view calculation history" ON public.price_calculation_history TO authenticated USING (public.is_active_staff() AND (EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id=auth.uid() AND ur.role::text IN ('admin','super_admin')) OR EXISTS (SELECT 1 FROM public.employees e WHERE lower(e.email)=lower(auth.jwt()->>'email') AND coalesce(e.permissions,ARRAY[]::text[]) && ARRAY['Administration','Procurement','Finance','Finance Management','Data Analysis','Quality Control'])));